div.div:
~ NOMBRE_DESPENSA: String {static, final}
~ INTERVALO_HILO_SEG: int = 10 {static, final}
~ DIAS_AVISO: int = 3 {static, final}
~ OPCION_SALIR: int = 10 {static, final}
~ OPCION_TEST: int = 11 {static, final} (oculta)
~ sc: Scanner {static}
~ carpetaDatos, archivoDespensa, archivoLista: File {static}
~ despensa: Despensa {static}
~ lista: ListaSuper {static}
~ hilo: HiloCaducidad {static}
~ pasan, fallan: int {static}

+ ANCHO: int = 78 {static, final}
- COLOR: boolean {static, final} (-Dcolor=false)
+ RESET, NEGRITA, TENUE, ROJO, VERDE,
AMARILLO, AZUL, MAGENTA, CYAN: String {static, final}

- Consola() (no se instancia)
// Formato
+ color(codigo, texto): String {static}
+ colorEstado(estado): String {static}
// Pantalla
+ limpiar() / titulo(t) / subtitulo(t) / separador() {static}
+ opcion(numero, texto): void {static}
+ ok(t) / error(t) / aviso(t) / info(t): void {static}

- despensa: Despensa {final}
- intervaloSeg: int {final}
- diasAviso: int {final}
- activo: boolean {volatile}
- hilo: Thread
- avisos: Lista<String>
- ultimaFirma: String
- hayNuevos: boolean
- revisiones: int

+ ListaSuper()
// Generar
+ generar(despensa: Despensa): int
// Extras
+ agregarExtra(texto: String): boolean
+ quitarExtra(numero: int): boolean
// Salida
+ renglones(): Lista<String>
+ estaVacia(): boolean
// Getters
+ getPendientes(): Lista<Producto>
+ getExtras(): Lista<String>

- GestorArchivos() (no se instancia)
// Despensa (data/despensa.txt)
+ guardarDespensa(d: Despensa, archivo: File): boolean {static}
+ cargarDespensa(nombre: String, archivo: File): Despensa {static}
+ crearDesdeLinea(linea: String): Producto {static}
// Lista del super (data/lista_super.txt)
+ exportarLista(l: ListaSuper, archivo: File): boolean {static}
// Auxiliares
- crearCarpeta(archivo: File): void {static}
- ahora(): String {static}

+ Producto(nombre, cantidad, cantidadMinima, unidad)
// Abstractos
+ getTipo(): String {abstract}
+ estaVencido(): boolean {abstract}
// Reglas (se pueden sobrescribir)
+ necesitaReponer(): boolean
+ cantidadAComprar(): double
+ getEstado(): String
+ getDetalle(): String
// Operaciones
+ consumir(cuanto: double): boolean
+ reabastecer(cuanto: double): boolean
+ datosValidos(nombre, cantidad, minima): boolean {static}
+ formato(valor: double): String {static}
+ toLinea(): String (@Override)
// Getters / Setters
+ getNombre(): String
+ getCantidad() / getCantidadMinima(): double
+ getUnidad(): Unidad
+ setCantidadMinima(m: double): void
+ toString(): String

+ TIPO: String = "PERECEDERO" {static, final}
+ FORMATO_FECHA: DateTimeFormatter {static, final}
- fechaCaducidad: LocalDate

+ TIPO: String = "LIMPIEZA" {static, final}
+ MARGEN: double = 1.5 {static, final}
- peligroso: boolean

- head: Nodo<V> {transient}
- tail: Nodo<V> {transient}
+ size: int {transient}
